  ["Help!"] = "Ajuda!",
  ["Help! Ah! Ahhhhh... oh, it doesn't seem to hurt that much anymore."] = "Ajuda! Ah! Ahhhhh... ah, parece que não dói mais tanto.",
  ["Help! Save me! My body, my body is out of control!"] = "Ajuda! Salve-me! Meu corpo, meu corpo está fora de controle!",
  ["Help! The rats are eating people!"] = "Ajuda! Os ratos estão comendo pessoas!",
  ["Help! I just finished organizing the receipts in order!"] = "Ajuda! Acabei de organizar os recibos em ordem!",
