  ["Beacon Mark"] = "Marca de farol",
  ["Reveal Cards"] = "Revelar cartas",
  ["Understood"] = "Entendido",
  ["Understood. We can try to balance the calculation using this rule."] = "Entendido. Podemos tentar equilibrar o cálculo usando esta regra.",
  ["Understood. Mr. Miller, after filling out the form, please go with Mr. Glet, he will arrange your work."] = "Entendido. Sr. Miller, após preencher o formulário, por favor vá com o Sr. Glet, ele providenciará seu trabalho.",
  ["Understood, I will negotiate with the survivor."] = "Entendido, negociarei com o sobrevivente.",
  ["Understood, I will make your wish come true!"] = "Entendido, vou realizar o seu desejo!",
  ["Understood, thank you, I have learned some more Beyonder knowledge."] = "Entendido, obrigado, aprendi mais alguns Beyonder conhecimentos.",
  ["Understand what..."] = "Entenda o que...",
  ["Understand what?"] = "Entender o quê?",
  ["Understood, leave it to me!"] = "Entendido, deixe comigo!",
  ["Understood, leave tonight to me. You go home and rest early."] = "Entendido, deixe esta noite comigo. Você vai para casa e descansa cedo.",
  ["Bright and Moving"] = "Brilhante e comovente",
